 if(!lateMail||!s){$('lateMailStamp').textContent=lateMail?'No saved check for this race yet.':'No saved check available yet.';$('lateMailSchedule').textContent='The original guide and published tips are still available.';$('lateMailBadge').textContent='AWAITING UPDATE';$('savedConditions').innerHTML='';$('lateMailComparison').innerHTML='<p class="mail-quiet">Late mail will appear after a saved race check.</p>';for(const id of ['lateMailFactors','lateMailGear','lateMailOpinions','lateMailResults'])$(id).innerHTML='';renderFormResult();return}
 const report=lateMail.meeting.races.find(r=>r.number===race.number),winner=report?.status==='official'?report.winners:[],before=s.baselineTip,after=s.revisedTip?.reliable===false?null:s.revisedTip,changed=!!after&&before?.name!==after.name;
 const savedPick=after||before,pickRunner=savedPick&&report?.runners?.find(h=>horseKey(h.name)===horseKey(savedPick.name)),pickWon=!!savedPick&&winner.some(w=>horseKey(w.name)===horseKey(savedPick.name));
 const outcome=winner.length?savedResultOutcome(report,s):null;
 const officialResult=winner.length?`<section class="official-race-result result-${outcome.kind}" aria-label="Official race result"><span>OFFICIAL RESULT · RACE ${report.number}</span><div><small>Winner:</small><strong>${winner.map(w=>`${w.number?`#${w.number} `:''}${esc(M.title(w.name))}`).join(' / ')}</strong>${officialReturn(reportedPlacings(report)[0])?`<em>${officialReturn(reportedPlacings(report)[0])}</em>`:''}</div><p><b>Saved pre-race tip:</b> ${savedPick?`${esc(savedPick.display)} · ${pickWon?'won':placingLabel(pickRunner?.placing)}${officialReturn(pickRunner)?` · ${officialReturn(pickRunner)}`:''}`:'No reliable saved tip'}</p><p class="result-verdict result-${outcome.kind}"><b>${outcome.label}</b><span>${esc(outcome.headline)}</span><small>${esc(outcome.detail)}</small></p></section>`:'';
 $('lateMailStamp').textContent=`Updated ${mailDate(lateMail.updated)}${!s.frozen&&Date.now()-Date.parse(s.checked||lateMail.updated)>7200000?' · race-day check pending':''}${mailReadError?(mailReadError==='fallback'?' · showing the saved fallback':' · showing the earlier verified edition'):lateMail.lastAttempt?.success===false?' · latest check failed; prior edition kept':''}`;
 const next=nextPlannedRaceCheck();$('lateMailSchedule').textContent=lateMail.automation?.enabled?(next?`Next planned check ~${mailClock(next)}. Source cooldowns can delay it.`:'Today’s scheduled checks are complete.'):'Saved preview. Automatic race-day checks are not enabled.';
 $('lateMailBadge').textContent=winner.length?'RESULT OFFICIAL':s.status==='abandoned'?'ABANDONED':lateMail.runKey?.includes('final')?'RESULTS':lateMail.runKey?.includes('initial')?'SAVED PREVIEW':'PRE-RACE CHECK';
 const weather=lateMail.weather;$('savedConditions').innerHTML=`${report?.condition?`<span>${esc(report.condition)} going</span>`:'<span>Going not confirmed</span>'}${weather&&Number.isFinite(weather.temperature)?`<span>${weather.temperature}°C · saved weather</span>`:''}`;
 const learned=s.comparableResults>=3?`Earlier official races supplied ${s.comparableResults} comparable track-pattern samples; the bounded draw adjustment was ${Number(s.drawBias||0).toFixed(2)}.`:`Earlier results were reviewed, but only ${s.comparableResults||0} comparable sample${s.comparableResults===1?'':'s'} were available, so they did not alter the tip.`;
 const displayPick=s.frozen?(after||before):(after||s.provisionalLeader),displayPickLabel=displayPick?esc(displayPick.display):'No pick available',formLeader=baseline.find(h=>h.eligible&&h.history.length),displayPickNote=s.frozen?'Saved before jump':after?(changed?'Revised selection':'Saved selection'):displayPick?'Leading watch · firm selection pending':'Awaiting sufficient race evidence';
 const material=(lateMail.changes?.[String(race.number)]||[]).filter(c=>c.type!=='gear'||c.newSinceBaseline!==false).sort((a,b)=>({track:5,scratching:5,rider:4,gear:3}[b.type]||0)-({track:5,scratching:5,rider:4,gear:3}[a.type]||0)).slice(0,2),changeText=c=>c.type==='track'?`Going: ${c.from} → ${c.to}`:c.type==='scratching'?`${c.horse} scratched`:`${c.horse||'Runner'}: ${c.type} ${c.to||'changed'}`;
 $('lateMailComparison').innerHTML=`${officialResult}${interimPlacingsHTML(report)}<div class="mail-picks"><div><span>FORM LADDER LEADER</span><b>${formLeader?esc(formLeader.display):'No original leader'}</b></div><i>→</i><div class="${changed?'mail-revised':''}"><span>${s.frozen?'SAVED PRE-RACE VIEW':'LATEST SAVED LEADER'}</span><b>${displayPickLabel}</b><small>${displayPickNote}</small></div></div>${runnerEvidenceMarkup(displayPick)}${material.length?`<div class="key-late-changes"><b>KEY CHANGES</b>${material.map(c=>`<p>${esc(changeText(c))}</p>`).join('')}</div>`:''}${confidenceMarkup(displayPick,{live:!s.frozen,checked:s.checked,going:M.ground(s.reportedGoing),assessment:after?s.confidence:undefined})}<details class="mail-learning"><summary>What today’s results changed${s.comparableResults>=3?'':' · no adjustment yet'}</summary><p>${esc(learned)}</p></details>`;
 $('groundScenarios').innerHTML=(s.scenarioPicks||[]).map(x=>`<div class="mail-result"><b>${esc(x.going)}</b><span>${esc(x.tip?.display||'No leader')}<small>${esc(x.confidence?.label||'Low confidence')} · hypothetical</small></span></div>`).join('')||'<p class="mail-quiet">No saved scenario comparison yet.</p>';
